import{_ as a,c as r,o as i,ae as t}from"./chunks/framework.BtEkjhVd.js";const m=JSON.parse('{"title":"Architecture Decision Record 1: Maplibre GL for Web Mapping Library","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/adr-choose-webmap-library/adr1.md","filePath":"architecture/adr-choose-webmap-library/adr1.md"}'),n={name:"architecture/adr-choose-webmap-library/adr1.md"};function o(s,e,l,c,d,p){return i(),r("div",null,e[0]||(e[0]=[t('<h1 id="architecture-decision-record-1-maplibre-gl-for-web-mapping-library" tabindex="-1">Architecture Decision Record 1: Maplibre GL for Web Mapping Library <a class="header-anchor" href="#architecture-decision-record-1-maplibre-gl-for-web-mapping-library" aria-label="Permalink to &quot;Architecture Decision Record 1: Maplibre GL for Web Mapping Library&quot;">​</a></h1><p>Date: 01/09/2024</p><h1 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h1><p>We are building a web application that requires rendering medium to large sized polygons on a map interface. The solution must integrate well with React.js, be fast and performant, and should not significantly increase the bundle size. The development team is familiar with OpenLayers, Leaflet, MapLibre GL, and Deck.GL, making them all viable options. Given the nature of our use case, the focus is on performance, rendering capabilities, and overall size efficiency.</p><h2 id="decision-drivers" tabindex="-1">Decision Drivers <a class="header-anchor" href="#decision-drivers" aria-label="Permalink to &quot;Decision Drivers&quot;">​</a></h2><ul><li>Ability to render medium to large polygons efficiently.</li><li>Integration with React.js libraries.</li><li>Performance, particularly in rendering and interaction with polygon geometries.</li><li>Library size and impact on the overall application bundle.</li><li>License</li></ul><h2 id="considered-options" tabindex="-1">Considered Options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered Options&quot;">​</a></h2><ul><li><p><a href="https://openlayers.org/" target="_blank" rel="noreferrer">OpenLayers</a>: Powerful for handling complex geometries, good performance for rendering large datasets, robust features for mapping. However, it has a larger bundle size compared to others, and may require more customization to integrate smoothly with React.js.</p></li><li><p><a href="https://leafletjs.com/" target="_blank" rel="noreferrer">Leaflet</a>: Lightweight, simple API, and easy integration with React.js (via react-leaflet). However, performance may degrade with large polygons, not as feature-rich for advanced rendering.</p></li><li><p><a href="https://maplibre.org/maplibre-gl-js/docs/" target="_blank" rel="noreferrer">MapLibre GL</a>: Good performance, especially with vector tiles and polygons, integrates well with React.js, supports WebGL for high-performance rendering. However, it may be slightly larger than Leaflet but smaller than OpenLayers, and lacks some advanced 3D features compared to Deck.GL.</p></li><li><p><a href="https://deck.gl/" target="_blank" rel="noreferrer">Deck.GL</a>: Excellent for rendering large-scale data visualizations, high-performance WebGL-based rendering, good React.js integration. However, it has the largest bundle size, may be overkill for simpler polygon rendering.</p></li></ul><h1 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h1><p>We will use MapLibre GL as the web mapping library for this project. It strikes the best balance between performance, polygon rendering capabilities, and integration with React.js. MapLibre GL offers good WebGL-based performance, making it suitable for rendering medium to large polygons, and its size is moderate compared to OpenLayers and Deck.GL.</p><p>All four options (OpenLayers, Leaflet, MapLibre GL, and Deck.GL) are licensed under very permissive open-source licenses (BSD or MIT) meaning they align with HOT license requirements.</p><h1 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h1><p>Proposed.</p><h1 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h1><p>This decision allows us to efficiently render medium to large polygons while maintaining good performance and keeping the application bundle size manageable. Integration with React.js should be smooth, but there may be some learning curve in managing advanced features or configurations. The team will also need to monitor and manage bundle size as new features are added to avoid bloat.</p>',15)]))}const g=a(n,[["render",o]]);export{m as __pageData,g as default};
